import { _decorator, Component } from 'cc';
import { EventBus, GameEvents } from '../core/EventBus';
const { ccclass } = _decorator;

@ccclass('PlayerStats')
export class PlayerStats extends Component {
    public level = 1;
    public exp = 0;
    public expToNext = 100;

    public maxHP = 100;
    public hp = 100;
    public maxMP = 50;
    public mp = 50;
    public maxStamina = 100;
    public stamina = 100;

    // Base attributes (modified by equipment)
    public baseAttack = 10;
    public baseDefense = 5;
    public baseMoveSpeed = 6;

    // Bonuses from equipment
    public bonusAttack = 0;
    public bonusDefense = 0;
    public bonusHP = 0;
    public bonusMP = 0;

    public gold = 50;

    get attack() { return this.baseAttack + this.bonusAttack + (this.level - 1) * 2; }
    get defense() { return this.baseDefense + this.bonusDefense + (this.level - 1); }

    update(dt: number) {
        // Regen stamina
        if (this.stamina < this.maxStamina) {
            this.stamina = Math.min(this.maxStamina, this.stamina + 18 * dt);
        }
        // Slight MP regen
        if (this.mp < this.maxMP) {
            this.mp = Math.min(this.maxMP, this.mp + 3 * dt);
        }
        EventBus.emit(GameEvents.PLAYER_STATS_CHANGED, this);
    }

    takeDamage(amount: number) {
        const real = Math.max(1, amount - this.defense);
        this.hp = Math.max(0, this.hp - real);
        EventBus.emit(GameEvents.PLAYER_DAMAGED, real, this.hp);
        EventBus.emit(GameEvents.PLAYER_STATS_CHANGED, this);
        if (this.hp <= 0) EventBus.emit(GameEvents.PLAYER_DIED);
    }

    heal(amount: number) {
        this.hp = Math.min(this.maxHP + this.bonusHP, this.hp + amount);
        EventBus.emit(GameEvents.PLAYER_HEALED, amount, this.hp);
        EventBus.emit(GameEvents.PLAYER_STATS_CHANGED, this);
    }

    useMP(amount: number): boolean {
        if (this.mp < amount) return false;
        this.mp -= amount;
        EventBus.emit(GameEvents.PLAYER_STATS_CHANGED, this);
        return true;
    }

    useStamina(amount: number): boolean {
        if (this.stamina < amount) return false;
        this.stamina -= amount;
        EventBus.emit(GameEvents.PLAYER_STATS_CHANGED, this);
        return true;
    }

    gainExp(amount: number) {
        this.exp += amount;
        EventBus.emit(GameEvents.PLAYER_EXP_GAINED, amount);
        while (this.exp >= this.expToNext) {
            this.exp -= this.expToNext;
            this.level++;
            this.expToNext = Math.floor(this.expToNext * 1.5);
            this.maxHP += 20; this.hp = this.maxHP + this.bonusHP;
            this.maxMP += 10; this.mp = this.maxMP + this.bonusMP;
            EventBus.emit(GameEvents.PLAYER_LEVEL_UP, this.level);
        }
        EventBus.emit(GameEvents.PLAYER_STATS_CHANGED, this);
    }

    addGold(amount: number) {
        this.gold += amount;
        EventBus.emit(GameEvents.PLAYER_STATS_CHANGED, this);
    }
}